def compile_es(f):
    flt, must, must_not = [], [], []
    if f["title_id"]:  flt.append({"term": {"title_id": f["title_id"]}})
    if f["seniority"]: flt.append({"term": {"seniority": f["seniority"]}})
    for s in f["skills"]:            # all-of: one term clause per skill
        flt.append({"term": {"skills": s}})
    if f["skills_not"]:
        must_not.append({"terms": {"skills": f["skills_not"]}})
    where = []                       # any city OR remote
    if f["location_ids"]: where.append({"terms": {"location_id": f["location_ids"]}})
    if f["remote_ok"]:    where.append({"term": {"open_to_remote": True}})
    if where:
        flt.append({"bool": {"should": where, "minimum_should_match": 1}})
    rng = {k: v for k, v in (f["salary"] or {}).items()
           if k in ("gte", "lte", "lt") and v is not None}
    if rng: flt.append({"range": {"salary_eur": rng}})
    if f["text"]: must.append({"match": {"profile_text": f["text"]}})
    q = {"filter": flt}
    if must: q["must"] = must
    if must_not: q["must_not"] = must_not
    return {"query": {"bool": q}}
